 fn retained_not_sent(&mut self,b:&ImmutableBinding,r:&str,min:u64)->feedback::Result<package_not_sent_evidence::VerifiedNotSent>{package_not_sent_evidence::VerifiedNotSent::read(&self.queue_dir,"fixture-account",b,r,min)}
 fn send(&mut self,_:multi_leg::Basket,_:Permit)->baal_transport_service::Result<multi_leg::Outcome>{panic!("legacy send forbidden")}
 fn read(&mut self,ep:Endpoint)->feedback::Result<Receipt>{self.cap=false;self.reads+=1;let (actual,tape)=match ep{Endpoint::OwnedOrder{order_id}=>(order_id,false),Endpoint::OwnedFills{order_id}=>(order_id,true),_=>panic!("unexpected package read")};assert!(self.ids.contains(&actual));let index=actual.chars().last().unwrap().to_digit(10).unwrap() as usize-1;let l=self.basket.as_ref().unwrap().legs[index].clone();let request=format!("get-{}",self.reads);self.admit(&request,false,None);let start=self.at;self.at+=1;self.command("network",&request,false,None,"");self.at+=1;self.command("complete",&request,false,None,"success");let no=l.side==multi_leg::Side::No;let side=if no{"no"}else{"yes"};let price=serde_json::from_str::<Value>(&l.limit_price).unwrap();let partial=self.partial&&index==0;let n=if partial{l.quantity/2}else{l.quantity};let data=if tape{let rows=if index==0{let first=l.quantity/2;let mut rows=vec![json!({"id":format!("{}8001",self.calls),"quantity":if no{-(first as i64)}else{first as i64},"side":side,"price":price,"filledAt":stamp(self.filled_at)})];if !partial{rows.push(json!({"id":format!("{}8101",self.calls),"quantity":if no{-((l.quantity-first)as i64)}else{(l.quantity-first)as i64},"side":side,"price":price,"filledAt":stamp(self.filled_at+1)}));}rows}else{vec![json!({"id":format!("{}8002",self.calls),"quantity":if no{-(n as i64)}else{n as i64},"side":side,"price":price,"filledAt":stamp(self.filled_at+1)})]};json!({"orderId":actual,"exchangeId":l.exchange_id,"tournamentId":T,"totalQuantityFilled":if no{-(n as i64)}else{n as i64},"coverage":{"complete":true},"pagination":{"hasMore":false,"nextCursor":null},"data":rows})}else{json!({"id":actual,"exchangeId":l.exchange_id,"tournamentId":T,"side":side,"action":l.action.wire(),"priceLimit":price,"quantity":l.quantity,"quantityFilled":if self.mismatch{n-1}else{n},"open":partial,"terminalReasonCode":null})};Ok(Receipt{endpoint:if tape{format!("/orders/{actual}/fills?limit=200&tournamentId={T}")}else{format!("/orders/{actual}")},status:200,request_started_at:stamp(start),received_at:stamp(self.at),data})
 }
